'use client'

import { useViewStore } from '@/stores/viewStore'
import { difficultyToY, getGradientForRange } from '@/lib/difficulty'
import type { Tournament, Round } from '@/lib/types'
import mwc2024 from '@data/tournaments/mwc-4k-2024.json'
import gbc2025 from '@data/tournaments/gbc-2025-spring.json'
import { useState, useRef } from 'react'
import { HoverCard } from './HoverCard'

const tournaments = [mwc2024, gbc2025] as unknown as Tournament[]

const DIFFICULTY_RANGE = { min: 0.5, max: 17.5 }

export function LadderView() {
  const { mode, zoom, columnWidth, rowHeight, activeFilter, searchQuery } = useViewStore()
  const containerRef = useRef<HTMLDivElement>(null)
  const [hoveredRound, setHoveredRound] = useState<{ round: Round; tournament: Tournament; x: number; y: number } | null>(null)
  const [hoverLocked, setHoverLocked] = useState(false)

  const diffRange = DIFFICULTY_RANGE.max - DIFFICULTY_RANGE.min
  const containerHeight = diffRange * rowHeight * zoom

  const filteredTournaments = tournaments.filter((t) => {
    if (!searchQuery) return true
    return t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.abbreviation.toLowerCase().includes(searchQuery.toLowerCase())
  })

  return (
    <div className="flex-1 overflow-auto relative ladder-container" ref={containerRef}>
      <div
        className="relative flex gap-2 px-2 pt-2"
        style={{ height: containerHeight, minWidth: filteredTournaments.length * (columnWidth + 8) }}
      >
        {filteredTournaments.map((tournament) => (
          <TournamentColumn
            key={tournament.id}
            tournament={tournament}
            mode={mode}
            containerHeight={containerHeight}
            columnWidth={columnWidth}
            activeFilter={activeFilter}
            onHover={(round, x, y) => { if (!hoverLocked) setHoveredRound({ round, tournament, x, y }) }}
            onLeave={() => { if (!hoverLocked) setHoveredRound(null) }}
          />
        ))}
      </div>

      {hoveredRound && (
        <HoverCard
          round={hoveredRound.round}
          tournament={hoveredRound.tournament}
          x={hoveredRound.x}
          y={hoveredRound.y}
          onMouseEnter={() => setHoverLocked(true)}
          onMouseLeave={() => { setHoverLocked(false); setHoveredRound(null) }}
        />
      )}
    </div>
  )
}

function TournamentColumn({
  tournament,
  mode,
  containerHeight,
  columnWidth,
  activeFilter,
  onHover,
  onLeave,
}: {
  tournament: Tournament
  mode: string
  containerHeight: number
  columnWidth: number
  activeFilter: string | null
  onHover: (round: Round, x: number, y: number) => void
  onLeave: () => void
}) {
  if (mode === 'tournament') {
    const allDiffs = tournament.rounds.flatMap((r) => [r.difficulty.min, r.difficulty.max])
    const minDiff = Math.min(...allDiffs)
    const maxDiff = Math.max(...allDiffs)
    const top = difficultyToY(maxDiff, containerHeight, DIFFICULTY_RANGE)
    const bottom = difficultyToY(minDiff, containerHeight, DIFFICULTY_RANGE)
    const height = Math.max(bottom - top, 32)

    return (
      <div className="relative shrink-0" style={{ width: columnWidth }}>
        <div className="text-xs text-center text-gray-500 truncate mb-1 font-medium">
          {tournament.abbreviation}
        </div>
        <div
          className="round-box absolute left-0 right-0"
          style={{
            top: top + 20,
            height,
            background: getGradientForRange(minDiff, maxDiff),
          }}
        >
          {tournament.abbreviation}
        </div>
      </div>
    )
  }

  return (
    <div className="relative shrink-0" style={{ width: columnWidth }}>
      <div className="text-xs text-center text-gray-500 truncate mb-1 font-medium">
        {tournament.abbreviation}
      </div>
      {tournament.rounds.map((round) => {
        const top = difficultyToY(round.difficulty.max, containerHeight, DIFFICULTY_RANGE)
        const bottom = difficultyToY(round.difficulty.min, containerHeight, DIFFICULTY_RANGE)
        const height = Math.max(bottom - top, 36)

        if (mode === 'type') {
          const types = getUniqueTypes(round)
          return types.map((type) => {
            const typeMaps = round.maps.filter((m) => m.type === type)
            const typeMin = Math.min(...typeMaps.map((m) => m.difficulty))
            const typeMax = Math.max(...typeMaps.map((m) => m.difficulty))
            const typeTop = difficultyToY(typeMax, containerHeight, DIFFICULTY_RANGE)
            const typeBottom = difficultyToY(typeMin, containerHeight, DIFFICULTY_RANGE)
            const typeHeight = Math.max(typeBottom - typeTop, 28)
            const isDimmed = activeFilter && activeFilter !== type

            return (
              <div
                key={`${round.id}-${type}`}
                className={`round-box absolute left-0 right-0 ${isDimmed ? 'dimmed' : ''}`}
                style={{
                  top: typeTop + 20,
                  height: typeHeight,
                  background: getGradientForRange(typeMin, typeMax),
                  fontSize: '10px',
                }}
                onMouseEnter={(e) => onHover(round, e.clientX, e.clientY)}
                onMouseLeave={onLeave}
              >
                <span className="truncate block w-full">{tournament.abbreviation} {round.abbreviation} {type}</span>
              </div>
            )
          })
        }

        const isDimmed = activeFilter && !round.maps.some((m) => m.type === activeFilter)

        return (
          <div
            key={round.id}
            className={`round-box absolute left-0 right-0 ${isDimmed ? 'dimmed' : ''}`}
            style={{
              top: top + 20,
              height,
              background: getGradientForRange(round.difficulty.min, round.difficulty.max),
            }}
            onMouseEnter={(e) => onHover(round, e.clientX, e.clientY)}
            onMouseLeave={onLeave}
          >
            <span className="truncate block w-full">{tournament.abbreviation} {round.abbreviation}</span>
          </div>
        )
      })}
    </div>
  )
}

function getUniqueTypes(round: Round): string[] {
  const seen = new Set<string>()
  return round.maps
    .map((m) => m.type)
    .filter((t) => {
      if (seen.has(t)) return false
      seen.add(t)
      return true
    })
}
