'use client'

import type { Round, Tournament } from '@/lib/types'

export function HoverCard({
  round,
  tournament,
  x,
  y,
  onMouseEnter,
  onMouseLeave,
}: {
  round: Round
  tournament: Tournament
  x: number
  y: number
  onMouseEnter: () => void
  onMouseLeave: () => void
}) {
  const diffLabel = getDifficultyLabel(round.difficulty.average)

  const cardX = Math.min(x + 12, window.innerWidth - 280)
  const cardY = Math.min(y + 12, window.innerHeight - 200)

  return (
    <div
      className="fixed z-50 bg-white border border-gray-200 rounded-lg shadow-lg p-3 max-w-xs"
      style={{ left: cardX, top: cardY }}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <div className="font-semibold text-sm mb-1">
        {tournament.abbreviation} {round.abbreviation}
      </div>
      <div className="text-xs text-gray-600 mb-2">
        {diffLabel}
      </div>
      {tournament.forumUrl && (
        <a
          href={tournament.forumUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="text-xs text-blue-500 hover:underline block"
        >
          论坛帖
        </a>
      )}
      {tournament.wikiUrl && (
        <a
          href={tournament.wikiUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="text-xs text-blue-500 hover:underline block"
        >
          Wiki
        </a>
      )}
      <div className="text-xs text-gray-400 mt-1">
        {round.maps.length} 张谱面 · 难度 {round.difficulty.min.toFixed(1)} ~ {round.difficulty.max.toFixed(1)}
      </div>
    </div>
  )
}

function getDifficultyLabel(avg: number): string {
  if (avg >= 17) return '~η'
  if (avg >= 16) return '~ζ'
  if (avg >= 15) return '~ε'
  if (avg >= 14) return '~δ'
  if (avg >= 13) return '~γ'
  if (avg >= 12) return '~β'
  if (avg >= 11) return '~α'
  if (avg >= 10) return '~10th Dan'
  if (avg >= 9) return '~9th Dan'
  if (avg >= 8) return '~8th Dan'
  if (avg >= 7) return '~7th Dan'
  if (avg >= 6) return '~6th Dan'
  if (avg >= 5) return '~5th Dan'
  return `~${Math.floor(avg)}th Dan`
}
