'use client'

import { useViewStore } from '@/stores/viewStore'
import { difficultyToY } from '@/lib/difficulty'
import reformDanData from '@data/scales/reform-dan.json'
import lnDanData from '@data/scales/ln-dan.json'
import type { DanLevel } from '@/lib/types'

const reformLevels = reformDanData.levels as DanLevel[]
const lnLevels = lnDanData.levels as DanLevel[]

const DIFFICULTY_RANGE = { min: 0.5, max: 17.5 }

const MAJOR_LEVELS = new Set([
  'eta', 'zeta', 'epsilon', 'delta', 'gamma', 'beta', 'alpha',
  'rf10', 'rf9', 'rf8', 'rf7', 'rf6', 'rf5', 'rf4', 'rf3', 'rf2', 'rf1',
  'intro3', 'intro2', 'intro1',
])

export function LeftScale() {
  const { zoom, rowHeight, activeFilter } = useViewStore()
  const diffRange = DIFFICULTY_RANGE.max - DIFFICULTY_RANGE.min
  const containerHeight = diffRange * rowHeight * zoom

  const showLn = activeFilter === 'LN'
  const levels = showLn ? lnLevels : reformLevels
  const majorSet = showLn
    ? new Set(lnLevels.filter((l) => !l.id.includes('+') && !l.id.includes('-')).map((l) => l.id))
    : MAJOR_LEVELS

  return (
    <div className="w-[100px] border-r border-gray-200 relative overflow-hidden shrink-0">
      <div className="text-xs text-center text-gray-400 py-1 border-b border-gray-100 font-medium">
        {showLn ? 'LN 段' : '难度 (RF)'}
      </div>
      <div className="relative" style={{ height: containerHeight }}>
        {levels.map((level) => {
          const y = difficultyToY(level.numericValue, containerHeight, DIFFICULTY_RANGE)
          const isMajor = majorSet.has(level.id)

          return (
            <div
              key={level.id}
              className="absolute left-0 right-0 flex items-center"
              style={{ top: y - 8 }}
            >
              <span
                className="scale-label pl-2 pr-1"
                style={{
                  color: level.color,
                  fontSize: isMajor ? '13px' : '10px',
                  opacity: isMajor ? 1 : 0.6,
                }}
              >
                {level.name}
              </span>
              <div
                className="flex-1 h-px"
                style={{ backgroundColor: isMajor ? '#e5e7eb' : 'transparent' }}
              />
            </div>
          )
        })}
      </div>
    </div>
  )
}
