'use client'

import { useViewStore } from '@/stores/viewStore'
import { difficultyToY } from '@/lib/difficulty'
import referencesData from '@data/references.json'

const DIFFICULTY_RANGE = { min: 0.5, max: 17.5 }

export function RightReferences() {
  const { zoom, rowHeight } = useViewStore()
  const diffRange = DIFFICULTY_RANGE.max - DIFFICULTY_RANGE.min
  const containerHeight = diffRange * rowHeight * zoom

  return (
    <div className="w-[180px] border-l border-gray-200 relative overflow-hidden shrink-0">
      <div className="text-xs text-center text-gray-400 py-1 border-b border-gray-100 font-medium">
        参考标尺
      </div>
      <div className="relative" style={{ height: containerHeight }}>
        {referencesData.points.map((point) => {
          const y = difficultyToY(point.difficulty, containerHeight, DIFFICULTY_RANGE)
          return (
            <div
              key={point.label}
              className="absolute left-0 right-0 flex items-center"
              style={{ top: y - 8 }}
            >
              <div className="w-3 h-px bg-purple-300 mr-1" />
              <span className="text-xs text-gray-600 truncate">{point.label}</span>
            </div>
          )
        })}
      </div>
    </div>
  )
}
