'use client'

import { useViewStore } from '@/stores/viewStore'

export function ControlBar() {
  const { zoom, setZoom, columnWidth, setColumnWidth, rowHeight, setRowHeight } = useViewStore()

  return (
    <footer className="h-16 border-t border-gray-200 flex items-center px-4 gap-6 shrink-0 bg-gray-50">
      <div className="flex items-center gap-2">
        <span className="text-xs text-gray-500">缩放</span>
        <button
          onClick={() => setZoom(Math.max(0.5, zoom - 0.1))}
          className="w-6 h-6 rounded bg-gray-200 text-sm flex items-center justify-center hover:bg-gray-300"
        >
          -
        </button>
        <span className="text-xs w-10 text-center">{Math.round(zoom * 100)}%</span>
        <button
          onClick={() => setZoom(Math.min(3, zoom + 0.1))}
          className="w-6 h-6 rounded bg-gray-200 text-sm flex items-center justify-center hover:bg-gray-300"
        >
          +
        </button>
      </div>

      <div className="flex items-center gap-2">
        <span className="text-xs text-gray-500">列宽</span>
        <input
          type="range"
          min={100}
          max={250}
          value={columnWidth}
          onChange={(e) => setColumnWidth(Number(e.target.value))}
          className="w-24 h-1 accent-purple-600"
        />
        <span className="text-xs w-8">{columnWidth}</span>
      </div>

      <div className="flex items-center gap-2">
        <span className="text-xs text-gray-500">行高</span>
        <input
          type="range"
          min={20}
          max={80}
          value={rowHeight}
          onChange={(e) => setRowHeight(Number(e.target.value))}
          className="w-24 h-1 accent-purple-600"
        />
        <span className="text-xs w-8">{rowHeight}</span>
      </div>

      <div className="ml-auto text-xs text-gray-400">
        osu!mania Difficulty Ladder v0.1
      </div>
    </footer>
  )
}
